  "crm": {"src/custom/actions/merge-customers.test.ts":"// Tests for the customer merge (merge-customers.ts): custom logic needs its own tests.\nimport { eq } from \"drizzle-orm\";\nimport { describe, expect, test } from \"vitest\";\nimport { db } from \"#/db\";\nimport { customers, orders } from \"#/db/schema\";\nimport { mergeCustomers } from \"./merge-customers\";\n\ndescribe(\"merging customers\", () => {\n  test(\"orders move, empty fields are filled, and the duplicate is gone\", async () => {\n    const keep = db\n      .insert(customers)\n      .values({ name: \"Arctic Oy\", phone: \"+358 40 1\" })\n      .returning()\n      .get();\n    const duplicate = db\n      .insert(customers)\n      .values({\n        name: \"Arctic\",\n        email: \"sales@arctic.example\",\n        phone: \"+358 40 2\",\n      })\n      .returning()\n      .get();\n    db.insert(orders).values({ number: \"M-1\", customerId: duplicate.id, total: 1000 }).run();\n    db.insert(orders).values({ number: \"M-2\", customerId: duplicate.id, total: 2000 }).run();\n\n    await mergeCustomers({ keep: keep.id, duplicate: duplicate.id });\n\n    const kept = db.select().from(customers).where(eq(customers.id, keep.id)).get();\n    expect(kept?.name).toBe(\"Arctic Oy\");\n    expect(kept?.phone).toBe(\"+358 40 1\");\n    expect(kept?.email).toBe(\"sales@arctic.example\");\n    expect(db.select().from(customers).where(eq(customers.id, duplicate.id)).get()).toBeUndefined();\n    const moved = db.select().from(orders).where(eq(orders.customerId, keep.id)).all();\n    expect(moved.map((o) => o.number).sort()).toEqual([\"M-1\", \"M-2\"]);\n  });\n\n  test(\"a customer is not merged into itself\", async () => {\n    const one = db.insert(customers).values({ name: \"Solo\" }).returning().get();\n    await expect(mergeCustomers({ keep: one.id, duplicate: one.id })).rejects.toThrow(\n      \"two different\",\n    );\n  });\n});\n","src/custom/actions/merge-customers.ts":"// Your implementation of the \"mergeCustomers\" action in smithable.yml. Smithable created this file\n// once and never changes it. The input and output types are generated from the spec, so a change\n// to the action's input or output shows up here as a type error.\n// The signed-in user is `await currentViewer()` from \"#/lib/viewer.server\"; the data functions\n// in src/generated/*.server.ts check access for them.\nimport { eq, getTableColumns } from \"drizzle-orm\";\nimport { db } from \"#/db\";\nimport { customers, orders } from \"#/db/schema\";\nimport type {\n  MergeCustomersInput,\n  MergeCustomersOutput,\n} from \"#/generated/actions/merge-customers\";\n\ntype Customer = typeof customers.$inferSelect;\n\n/**\n * Merge a duplicate customer record into the one we keep.\n *\n * Rules (from smithable.yml):\n * - All orders of the duplicate move to the kept customer.\n * - Empty fields on the kept customer are filled from the duplicate.\n * - The duplicate is deleted afterwards.\n */\nexport async function mergeCustomers({\n  keep,\n  duplicate,\n}: MergeCustomersInput): Promise<MergeCustomersOutput> {\n  if (keep === duplicate) throw new Error(\"Choose two different customers.\");\n  // Only admins may run this action (smithable.yml); the generated action checks that first.\n  const kept = db.select().from(customers).where(eq(customers.id, keep)).get();\n  const other = db.select().from(customers).where(eq(customers.id, duplicate)).get();\n  if (!kept || !other) throw new Error(\"Both customers must exist.\");\n  const empty = (value: unknown) => value === null || value === undefined || value === \"\";\n  // Every column the kept customer has no value for, taken from the duplicate.\n  const filled = Object.fromEntries(\n    Object.keys(getTableColumns(customers))\n      .filter((column) => column !== \"id\")\n      .filter((column) => empty(kept[column as keyof Customer]))\n      .filter((column) => !empty(other[column as keyof Customer]))\n      .map((column) => [column, other[column as keyof Customer]]),\n  );\n  // All at once or not at all. The duplicate goes before its values move, so a unique value\n  // (its email) is never on two customers at the same time.\n  db.transaction((tx) => {\n    tx.update(orders).set({ customerId: keep }).where(eq(orders.customerId, duplicate)).run();\n    tx.delete(customers).where(eq(customers.id, duplicate)).run();\n    if (Object.keys(filled).length)\n      tx.update(customers).set(filled).where(eq(customers.id, keep)).run();\n  });\n}\n"},
